import openpyxl

wb = openpyxl.load_workbook("./materials/FinancialStatementFY26Q4.xlsx", data_only=False)
print("Sheet names:", wb.sheetnames)

# Focus on the three sheets we need
for sname in ['Segment Results', 'Income Statement', 'Balance Sheet']:
    if sname in wb.sheetnames:
        ws = wb[sname]
        print(f"\n=== Sheet: {sname} ===")
        print(f"  Max row: {ws.max_row}, Max col: {ws.max_column}")
        for row in ws.iter_rows(min_row=1, max_row=min(60, ws.max_row), values_only=False):
            vals = []
            for cell in row:
                v = cell.value
                if v is not None:
                    vals.append(f"{cell.coordinate}={v}")
            if vals:
                print("  ", " | ".join(vals))
