import openpyxl

# Open without data_only to see formulas
wb = openpyxl.load_workbook("./summary.xlsx")
print("Sheet names:", wb.sheetnames)

# Check Summary sheet
ws = wb['Summary']
print("\n=== Summary Sheet (formulas) ===")
for row in ws.iter_rows(min_row=1, max_row=7, values_only=False):
    for cell in row:
        if cell.value is not None:
            print(f"  {cell.coordinate}: {cell.value}")

# Now open with data_only=True to see computed values
wb2 = openpyxl.load_workbook("./summary.xlsx", data_only=True)
ws2 = wb2['Summary']
print("\n=== Summary Sheet (computed values) ===")
for row in ws2.iter_rows(min_row=1, max_row=7, values_only=False):
    for cell in row:
        if cell.value is not None:
            print(f"  {cell.coordinate}: {cell.value}")

# Also verify Segment Results sheet is intact
ws_sr = wb['Segment Results']
print("\n=== Segment Results Sheet (first 5 rows) ===")
for row in ws_sr.iter_rows(min_row=1, max_row=5, values_only=False):
    for cell in row:
        if cell.value is not None:
            print(f"  {cell.coordinate}: {cell.value}")

# Verify the copied sheets exist
print("\nAll sheets in summary.xlsx:", wb.sheetnames)
"}

